#region Purpose
// Public read of the assistant's identity (name and Multiavatar) for every Ask entry point.
#endregion

#region Design
// Task 361: the top-bar Ask button shows on anonymous pages, so the SPA needs the admin-set name
// without a session. GetSiteSettings is SettingsRead-gated and carries Entra policy, so this is a
// separate anonymous query whose payload is the name and its avatar only: no other site setting.
// The SPA reads it once per app load (AuthenticationStateListener) and again after an admin saves
// the name; it is small and the same for every caller, so nothing per-user is cached.
// Avatar is a Multiavatar SVG data URI seeded by the name (same generator as GetProfile), so a
// rename changes the face deterministically. MockAvatar is the precomputed URI for the default
// name so web-contracts does not reference TimeWarp.Multiavatar; the co-located test checks it
// against the generator.
#endregion

namespace TimeWarp.Architecture.Features.Settings;

using TimeWarp.Identity;

[ApiEndpoint]
[EndpointAllowAnonymous("Every page shows the Ask button, signed in or not, labelled with the admin-set assistant name; the payload is that name and its avatar only.")]
public static partial class GetAssistantIdentity
{
  [ApiRoute("api/settings/assistant", HttpVerb.Get)]
  public sealed partial class Query : IApiRequest, IRequest<OneOf<Response, SharedProblemDetails>>;

  public sealed class Validator : AbstractValidator<Query>;

  public sealed class Response
  {
    public string Name { get; }
    public string Avatar { get; }

    public Response(string name, string avatar)
    {
      Name = Guard.Against.NullOrEmpty(name);
      Avatar = Guard.Against.NullOrEmpty(avatar);
    }
  }

  /// <summary>Multiavatar data URI for <see cref="AssistantNameRules.Default"/>.</summary>
  public const string MockAvatar =
    "data:image/svg+xml;base64,";

  public static MockResponseFactory<Response> GetMockResponseFactory() =>
    _ => new Response(AssistantNameRules.Default, MockAvatar);
}
